from fig3 import *
K=lambda c='#1d6fb8': person(c)
Q=lambda c='#c0392b': person(c)
S=sage; V=vishnu
G=lambda s=1: ganesha(seat=False)
# Order: Karnataka (amānta) month order, Caitra first. pm = northern (pūrṇimānta) month.
SK=[]
def e(**d): SK.append(d)
CORE='Pārvatī asks Gaṇeśa which form is worshipped this month; Gaṇeśa answers by retelling what Kṛṣṇa told Yudhiṣṭhira during the Pāṇḍavas’ exile.'
e(slug='vikata',name='Vikaṭa',mon='Caitra',pm='Vaiśākha',form='Vikaṭa Mahāgaṇapati',pitha='Vināyaka pīṭha',
 mean='“the extraordinary”, of a form beyond the ordinary (vikaṭa: huge, unusual, formidable)',
 teller=CORE,
 offering='The vrata book names a sweet of lotus seeds (kamalagaṭṭā) as the offering, and the same is eaten after worship.',
 strip=[panel([(Q('#c0392b'),.8),(Q('#2a9d6f'),.8)],'#fff3cf',140),panel([(Q('#c0392b'),.8),(G(),.5)],'#fde4e4',140),panel([(Q('#2a9d6f'),.8),(Q('#c0392b'),.8)],'#e3f2e3',140)],
 caps=['two wives','Suśīlā’s vow','the rival repents'],
 lead='A story of two co-wives, one who fasted and one who mocked her.',
 steps=['In the land of King Rantideva lived a learned brahmin, <b>Dharmaketu</b>, with two wives: <b>Suśīlā</b>, who kept many vows and grew thin, and <b>Cañcalā</b>, who kept none and stayed robust.','Suśīlā bore a daughter, Cañcalā a son, and Cañcalā mocked her: all that fasting, and only a frail girl to show for it.','Stung, Suśīlā kept the Saṅkaṣṭī vow. Gaṇeśa appeared and promised her a son learned in the scriptures; from then on gems fell from her daughter’s lips.','Dharmaketu died; Cañcalā took his wealth and left. Out of envy she pushed Suśīlā’s daughter into a well, but Gaṇeśa kept the girl safe.','Seeing this, Cañcalā broke down, begged forgiveness and took up the vow herself; the two women lived in friendship after that.'],
 chars=[('👩','Suśīlā','The faithful wife who keeps the vow through mockery and loss.'),('😏','Cañcalā','Her co-wife, scornful, then jealous, then repentant.'),('📜','Dharmaketu','The learned brahmin husband.'),('👧','The daughter','Protected in the well; gems fall from her lips.')],
 fruits='Removal of every obstacle; in Kṛṣṇa’s words to Yudhiṣṭhira, victory over enemies and the eight siddhis and nine treasures at the devotee’s feet.',
 custom='In Karnataka’s calendar this is the first Saṅkaṣṭī of the new year, coming soon after Ugādi.',
 talk=[('z','So the vow worked even for the one who mocked it?'),('b','Once she stopped mocking. The story’s real miracle is the change in Cañcalā.')],
 k='Mockery ends in <b>friendship</b>',
 lesson=['<b>Fasting is not weakness.</b> The story answers a taunt many have heard: why go without? Suśīlā’s strength is shown to be of another kind.','<b>Envy ruins the envious.</b> Cañcalā takes the wealth and is still unhappy; only when she joins the vow does peace come.'])
e(slug='ekadanta',name='Ekadanta',mon='Vaiśākha',pm='Jyeṣṭha',form='Cakrarāja Ekadanta Gaṇapati',pitha='Śrīcakra pīṭha',
 mean='“the one-tusked”, Gaṇeśa who gave up a tusk (eka: one, danta: tooth)',
 teller=CORE,
 offering='The vrata book names sweets and fried bread made in pure ghee; a brahmin is fed before the devotee eats.',
 strip=[panel([(Q('#c0392b'),.8),(Q('#7a3fa0'),.8)],'#fff3cf',140),panel([(K('#e0a800'),.8)],'#2a2a3a',140),panel([(K('#e0a800'),.7),(Q('#c0392b'),.7),(S(),.7)],'#fde4e4',140)],
 caps=['the vow is forbidden','the groom vanishes','the groom returns'],
 lead='A daughter-in-law gives up her childhood vow under pressure, and pays for it at her son’s wedding.',
 steps=['In King Pṛthu’s land lived the learned brahmin <b>Dayādeva</b> and his four sons. The eldest son’s wife had kept the Saṅkaṣṭī vow since childhood.','Her in-laws scorned it: why should a woman with no troubles keep a “trouble” vow? She kept it quietly, bore a son, but at last gave it up under their pressure.','Years later, on her son’s wedding day, the groom vanished from the pavilion. She told her father-in-law plainly: this came from forcing her to drop the vow.','The bride now kept the vow every month. One day a frail old brahmin came begging; she gave him a seat, food and clothes. He was Gaṇeśa, and granted her husband’s return.','A brahmin named Somaśarmā found the youth in the forest and brought him home; the wedding was held again, and the family took up the vow.'],
 chars=[('👩','The elder daughter-in-law','Who kept the vow from childhood, then gave it up.'),('👰','The bride','Whose faithful monthly vow brings her husband back.'),('👴','Dayādeva','The learned father-in-law who scorned the vow.'),('🙏','The old beggar','Gaṇeśa in disguise.')],
 fruits='Good fortune and a happy married life; in Kṛṣṇa’s words, the defeat of enemies.',
 custom='Many keep this Saṅkaṣṭī for harmony in marriage and in the joint family.',
 talk=[('z','Gaṇeśa came as a beggar?'),('b','A favourite test in the stories. How you treat the unexpected guest is how you treat God.')],
 k='A dropped vow, <b>a restored family</b>',
 lesson=['<b>Don’t make others drop their faith.</b> The trouble begins when the family forces a quiet practice to stop.','<b>The guest is sacred.</b> The bride’s simple hospitality to a frail beggar is what Gaṇeśa rewards.'])
e(slug='krishnapingala',name='Kṛṣṇapiṅgala',mon='Jyeṣṭha',pm='Āṣāḍha',form='Kṛṣṇapiṅgala Mahāgaṇapati',pitha='Śrī Śakti Gaṇapati pīṭha',
 mean='“the dark and tawny”, Gaṇeśa of dusky-golden hue (kṛṣṇa: dark, piṅgala: reddish-brown)',
 teller=CORE+' Within Kṛṣṇa’s telling, the sage Lomaśa gives the vow.',
 offering='The vrata book stresses gifts of food and clothes to brahmins after the vow; it names no special dish.',
 strip=[panel([(K('#e0a800'),.9),(palace(),.5)],'#fff3cf',140),panel([(S('#ff8c1a'),.9),(K('#1d6fb8'),.7),(K('#2a9d6f'),.7)],'#e3f2e3',140),panel([(Q('#c0392b'),.8),(child(),1)],'#fde4e4',140)],
 caps=['a childless king','the people go to Lomaśa','an heir is born'],
 lead='A good king has everything except a child, and his people go to find the answer for him.',
 steps=['In Māhiṣmatī ruled King <b>Mahījit</b>, just and kind, but childless; penance, gifts and sacrifices all failed.','He asked his brahmins and his people why, when he had ruled rightly, he still had no heir.','The people went into the forest to the ancient sage <b>Lomaśa</b>, so long-lived that one of his hairs is said to fall only at the end of each kalpa.','Lomaśa taught them the Saṅkaṣṭī vow for this month, with worship of Gaṇeśa and gifts of food and clothes.','The king kept it with his people; in time Queen <b>Sudakṣiṇā</b> bore a virtuous son.'],
 chars=[('👑','Mahījit','The good, childless king of Māhiṣmatī.'),('🧘','Lomaśa','The ancient sage who teaches the vow.'),('👥','The people','Who seek help on their king’s behalf.'),('👸','Sudakṣiṇā','The queen who bears the heir.')],
 fruits='Children for the childless and wealth for the poor; success and freedom from obstacles for those who hear the story.',
 custom='Couples praying for a child often keep this Saṅkaṣṭī. The vrata texts are not consistent about the form named for this month; we follow the common monthly list.',
 talk=[('z','This sounds like an Ekādaśī story!'),('b','It does: the same king appears in Śrāvaṇa Putradā Ekādaśī. Vrata books share their characters freely.')],
 k='The people’s prayer <b>for their king</b>',
 lesson=['<b>A people who care.</b> The citizens do the seeking. Good rule is repaid with loyalty.','<b>Vows can be kept for others.</b> As in many Ekādaśī stories, merit is gathered for someone else’s need.'])
e(slug='gajanana',name='Gajānana',mon='Āṣāḍha',pm='Śrāvaṇa',form='Gajānana Gaṇapati',pitha='Viṣṇu pīṭha',
 mean='“the elephant-faced” (gaja: elephant, ānana: face)',
 teller='The sages ask Skanda (Kārttikeya) for a remedy against poverty, illness, enemies and childlessness; Skanda tells what Kṛṣṇa taught Yudhiṣṭhira, and Kṛṣṇa tells of Pārvatī’s own vow.',
 offering='The vrata book is detailed here: a bath with white sesame in the water; an image on a kalaśa set on an eight-petalled lotus; fifteen ghee laḍḍus (five offered, five given away, five eaten after moonrise); arghya to the moon.',
 strip=[panel([(devi(),.6),(tree(),.7)],'#cfe0b8',140),panel([(devi(),.55),(G(),.5)],'#fff3cf',140),panel([(shiva(),.55),(devi(),.55)],'#e3eaf3',140)],
 caps=['Pārvatī’s penance','Gaṇeśa teaches her','Śiva and Pārvatī wed'],
 lead='Here the vow’s first keeper is Pārvatī herself, before her marriage.',
 steps=['Pārvatī, daughter of Himavān, did fierce penance in the forest to win Śiva, but Śiva did not come.','She called to mind Gaṇeśa, who appeared at once. (The stories never worry about how her son could exist before her marriage: Gaṇeśa is eternal.)','She said Nārada had told her of a vow that removes all obstacles, and asked Gaṇeśa to teach it.','Gaṇeśa taught her the Saṅkaṣṭī vow; she kept it, and her marriage to Śiva came about.','Skanda adds a roll of later keepers: Yudhiṣṭhira in exile, Hanumān searching for Sītā, Rāvaṇa after his humiliation by Vāli, and Ahalyā in her separation from Gautama.'],
 chars=[('🌸','Pārvatī','Who keeps the vow to win Śiva.'),('🐘','Gaṇeśa','Who teaches it to his own mother.'),('🦚','Skanda','Who tells the story to the sages.'),('🎶','Nārada','Who first told Pārvatī of the vow.')],
 fruits='All four aims of life; learning for the student, wealth for the seeker of wealth, children for the childless, health for the sick.',
 custom='The text allows the vow to be kept for life, for a year (twelve months), or at least for this one month.',
 talk=[('z','Gaṇeśa teaching his mother before he was born? How?'),('b','Gaṇeśa is beginningless; the Purāṇas happily let him help in any age. Don’t read it as a timeline.')],
 k='The vow that <b>won Pārvatī her Lord</b>',
 lesson=['<b>Even the goddess asks for help.</b> If Pārvatī turns to Gaṇeśa before a great undertaking, so may we.','<b>Persistence.</b> Pārvatī’s penance seemed to fail; the vow is the step that turned it.'])
e(slug='heramba',name='Heramba',mon='Śrāvaṇa',pm='Bhādrapada',form='Heramba Mahāgaṇapati',pitha='Gaṇapati pīṭha',
 mean='“protector of the helpless”, as tradition explains the name; in images, five-headed and riding a lion',
 teller=CORE,
 offering='The vrata book names no special dish for this month.',
 strip=[panel([(K('#e0a800'),.8),(Q('#c0392b'),.8)],'#fff3cf',140),panel([(K('#5a5a5a'),.8),(tree(),.6)],'#2a2a3a',140),panel([(Q('#c0392b'),.8),(S(),.8)],'#e3f2e3',140)],
 caps=['Nala and Damayantī','all is lost','the sage Śarabhaṅga'],
 lead='The great love story of Nala and Damayantī becomes, in the vrata book, a Saṅkaṣṭī story.',
 steps=['King <b>Nala</b> and his queen <b>Damayantī</b> lived happily until a curse fell on Nala.','Thieves took his elephants and horses, bandits looted his treasury, fire burned the rest; ministers deserted him and he lost the kingdom at dice.','The family was scattered: Nala tending horses in one town, Damayantī in another, their son elsewhere, all poor and sick.','In the forest Damayantī met the sage <b>Śarabhaṅga</b>, who told her to keep this Saṅkaṣṭī and worship Heramba.','She kept it each month; within three months she was reunited with Nala and their son, and the kingdom was restored.'],
 chars=[('👑','Nala','The king ruined by a curse and the dice.'),('👸','Damayantī','His faithful queen, who keeps the vow.'),('🧘','Śarabhaṅga','The forest sage who gives the vow.'),('🦁','Heramba','Gaṇeśa’s five-headed, lion-riding form.')],
 fruits='Reunion of the separated and the return of what was lost.',
 custom='In the north this day is also Bahulā Caturthī, when cows and calves are honoured; families pray for their children.',
 talk=[('z','Isn’t Nala’s story in the Mahābhārata?'),('b','Yes, told to Yudhiṣṭhira in exile. The vrata book adds the Saṅkaṣṭī thread; the epic itself doesn’t mention the vow.')],
 k='<b>Reunion</b> after ruin',
 lesson=['<b>Faith in the worst time.</b> Damayantī keeps the vow when she has nothing at all.','<b>A traditional gloss.</b> “Heramba” is explained as protector (ramba) of the helpless (he); a pious etymology, but a fitting one here.'])
e(slug='vighnaraja',name='Vighnarāja',mon='Bhādrapada',pm='Āśvina',form='Vighnarāja Mahāgaṇapati',pitha='Vighneśvara pīṭha',
 mean='“king of obstacles”: lord over them, both to place and to remove',
 teller='As commonly retold, the sage Lomaśa gives the vow to Kṛṣṇa himself. We could not read the standard vrata-book text for this month; the outline below follows popular retellings.',
 offering='Dūrvā, flowers and modakas, with the usual fast until moonrise.',
 strip=[panel([(K('#e0a800'),.8),(palace(),.5)],'#2a2a3a',140),panel([(S(),.8),(V(),.6)],'#e3f2e3',140),panel([(V(),.6),(K('#e0a800'),.8)],'#e3eaf3',140)],
 caps=['Aniruddha is carried off','Lomaśa advises Kṛṣṇa','Aniruddha is rescued'],
 lead='Even Kṛṣṇa, in this telling, keeps the vow before a hard battle.',
 steps=['Kṛṣṇa’s grandson <b>Aniruddha</b> was carried off to the city of the asura <b>Bāṇa</b>, a mighty devotee of Śiva.','Kṛṣṇa, troubled, was told by the sage <b>Lomaśa</b> to keep this month’s Saṅkaṣṭī.','Kṛṣṇa kept it as prescribed.','He then marched on Bāṇa’s city, overcame Bāṇa and freed Aniruddha, who had married Bāṇa’s daughter Uṣā.','Some retellings add a second account: Gaṇeśa as Vighnarāja himself defeating a demon of obstacles.'],
 chars=[('🌀','Kṛṣṇa','Who keeps the vow before battle.'),('🤴','Aniruddha','His grandson, held captive.'),('👹','Bāṇa','The thousand-armed asura king.'),('🧘','Lomaśa','The sage who advises the vow.')],
 fruits='Removal of obstacles before a difficult undertaking.',
 custom='This Saṅkaṣṭī falls soon after the great Gaṇeśa Caturthī festival of Bhādrapada; see our <a href="/ganesha/festivals/ganesha-chaturthi/">Gaṇeśa Caturthī</a> article.',
 talk=[('z','Why would Kṛṣṇa need a vow?'),('b','To teach. In the stories the greatest keep the rules so that others will.')],
 k='Even Kṛṣṇa <b>begins with Gaṇeśa</b>',
 lesson=['<b>Begin with Gaṇeśa.</b> Every great work, even Kṛṣṇa’s, starts by honouring the remover of obstacles.','<b>Marked as uncertain.</b> The story for this month varies most between sources; treat this telling as one among several.'])
e(slug='vakratunda',name='Vakratuṇḍa',mon='Āśvayuja',pm='Kārtika',form='Vakratuṇḍa Mahāgaṇapati',pitha='Bhuvaneśvarī pīṭha',
 mean='“of the curved trunk” (vakra: curved, tuṇḍa: trunk)',
 teller=CORE,
 offering='The vrata book prescribes a homa with ghee and black gram, one meal in the day, and feeding brahmins before eating quietly.',
 strip=[panel([(demon('#2a6a3a'),.9)],'#2a2a3a',140),panel([(S('#ff8c1a'),.8),(G(),.5)],'#fff3cf',140),panel([(S('#ff8c1a'),.8),(river(140,120),1)],'#cfe8f5',140)],
 caps=['Vṛtra’s demons hide','Agastya keeps the vow','the ocean is drunk'],
 lead='The sage Agastya’s most famous feat, drinking the ocean, is credited here to the vow.',
 steps=['The asura <b>Vṛtra</b> conquered the three worlds and drove out the gods; after his fall his demons hid in the ocean.','The gods ran to Viṣṇu, who told them to ask the sage <b>Agastya</b> to drink the ocean dry and expose the demons.','Agastya agreed, then wondered how anyone could drink an ocean a lakh of yojanas wide.','He kept the Saṅkaṣṭī vow for three months; pleased, Gaṇeśa gave him the power, and he drank the ocean with ease.','The same vow, the story adds, later helped Arjuna defeat the Nivātakavaca demons.'],
 chars=[('🧘','Agastya','The short sage of immense power.'),('👹','Vṛtra’s host','The demons hiding under the sea.'),('🌀','Viṣṇu','Who advises the gods.'),('🏹','Arjuna','A later keeper of the vow.')],
 fruits='Success in impossible tasks; hearing the story is praised as equal to great sacrifices.',
 custom='In the north this day is Karvā Cauth, when wives fast for their husbands and break the fast at moonrise.',
 talk=[('z','Drinking the ocean! Seriously?'),('b','It’s an image of the impossible made possible. Everyone has an ocean in front of them sometimes.')],
 k='The <b>impossible</b> made possible',
 lesson=['<b>Humility before the task.</b> Even Agastya pauses and asks for help.','<b>Preparation.</b> He keeps the vow for three months before the deed, not on the day.'])
e(slug='ganadhipa',name='Gaṇādhipa',mon='Kārtika',pm='Mārgaśīrṣa',form='Gaṇādhipa Mahāgaṇapati',pitha='Śiva pīṭha',
 mean='“lord of the gaṇas”, Śiva’s hosts (gaṇa: troop, adhipa: lord)',
 teller=CORE,
 offering='The vrata book names a full-day fast, arghya after worship, feeding brahmins, and a homa of barley, sesame, rice, sugar and ghee.',
 strip=[panel([(K('#e0a800'),.8),(bow(),.8)],'#cfe0b8',140),panel([(K('#ff8c1a'),.8),(bird(),.8)],'#fff3cf',140),panel([(hanuman(),.7),(river(140,120),1)],'#cfe8f5',140)],
 caps=['Daśaratha’s arrow','Sampāti sees Sītā','Hanumān leaps'],
 lead='The Rāmāyaṇa from Daśaratha’s fatal arrow to Hanumān’s leap, with the vow at the turning point.',
 steps=['King <b>Daśaratha</b>, hunting by sound, shot an arrow at what he took for an animal drinking; it killed young <b>Śravaṇa</b>, fetching water for his blind parents, who cursed the king to die grieving for a son.','Daśaratha later had Rāma and his brothers; in time Rāma was exiled, and Rāvaṇa carried off Sītā.','Rāma allied with Sugrīva; the vānaras searched south and met the old vulture <b>Sampāti</b>, Jaṭāyu’s brother, who could see Sītā in Laṅkā across the sea.','Hanumān asked how anyone could cross that ocean. Sampāti told him to keep the Saṅkaṣṭī vow.','Hanumān kept it, and crossed the sea in one leap.'],
 chars=[('🏹','Daśaratha','Whose hunting mistake begins the chain.'),('🦅','Sampāti','The vulture whose sight finds Sītā.'),('🙏','Hanumān','The vānara hero who keeps the vow and leaps.'),('🌸','Sītā','Held in Laṅkā across the sea.')],
 fruits='Crossing what seems uncrossable; victory over enemies; the return of what was lost.',
 custom='This Saṅkaṣṭī falls in the month of lamps; see our <a href="/festivals/kartika/">Kārtika</a> series.',
 talk=[('z','Hanumān needed a vow to jump?'),('b','In the Rāmāyaṇa he needed Jāmbavān to remind him of his strength. The vrata book makes the vow that reminder.')],
 k='The vow behind <b>the great leap</b>',
 lesson=['<b>Strength you forgot you had.</b> In Vālmīki, Hanumān’s power is awakened by reminder; here, by the vow. Both say the same thing.','<b>Mistakes have long shadows.</b> The story begins with a careless arrow whose curse shapes the whole epic.'])
e(slug='akhuratha',name='Ākhuratha',mon='Mārgaśīrṣa',pm='Pauṣa',form='Ākhuratha Mahāgaṇapati',pitha='Durgā pīṭha',
 mean='“whose chariot is the mouse” (ākhu: mouse, ratha: vehicle)',
 teller='As commonly retold, the sage Pulastya gives the vow to his grandson Rāvaṇa. We could not read the standard vrata-book text for this month; regional tellings differ.',
 offering='Dūrvā, flowers, a lamp and modakas, with arghya to the moon at moonrise.',
 strip=[panel([(demon('#7a1d12'),.9)],'#fde4e4',140),panel([(K('#b8741a'),.9),(child(),.9)],'#cfe0b8',140),panel([(S(),.8),(demon('#7a1d12'),.8)],'#fff3cf',140)],
 caps=['proud Rāvaṇa','Vāli and the boy Aṅgada','Pulastya’s advice'],
 lead='The proudest king of the Rāmāyaṇa learns humility in the vānara kingdom.',
 steps=['<b>Rāvaṇa</b>, swollen with pride after defeating the gods, tried to seize <b>Vāli</b>, the mighty vānara king of Kiṣkindhā.','Vāli caught him easily, tucked him under his arm and carried him home.','There he gave Rāvaṇa to his small son <b>Aṅgada</b> as a plaything; the boy tied him up and swung him about.','Hurt and humbled, Rāvaṇa called on <b>Pulastya</b>, who told him where pride leads, then advised the Saṅkaṣṭī vow (Indra, he said, had once escaped trouble the same way).','Rāvaṇa kept the vow and was set free.'],
 chars=[('👹','Rāvaṇa','The proud king of Laṅkā, humbled.'),('💪','Vāli','The vānara king who captures him.'),('👦','Aṅgada','Vāli’s son, who plays with the captive.'),('🧘','Pulastya','The sage who advises the vow.')],
 fruits='Release from captivity and humiliation.',
 custom='This is the Saṅkaṣṭī of the winter month of Mārgaśīrṣa, the month Kṛṣṇa calls his own in the Gītā.',
 talk=[('z','Even Rāvaṇa got help from Gaṇeśa?'),('b','Grace isn’t only for the good. But notice: first the lesson in humility, then the help.')],
 k='<b>Pride</b>, then release',
 lesson=['<b>Pride goes before a fall.</b> The great conqueror ends up a child’s toy.','<b>No one is refused.</b> Even Rāvaṇa may keep the vow; whether he learned the lesson, the Rāmāyaṇa shows otherwise.'])
e(slug='lambodara',name='Lambodara',mon='Pauṣa',pm='Māgha',form='Lambodara Mahāgaṇapati',pitha='Saura pīṭha',
 mean='“the big-bellied” (lamba: hanging, large; udara: belly), who holds the universe within',
 teller=CORE,
 offering='Ten sesame laḍḍus: five offered to Gaṇeśa, five given to a brahmin; the devotee eats what remains.',
 strip=[panel([(Q('#7a3fa0'),.8),(child(),.9)],'#fff3cf',140),panel([(flames(),.9),(child(),.8)],'#2a2a3a',140),panel([(child(),.9),(lotus(),.9),(durva(),1)],'#cfe8f5',140)],
 caps=['a widow and her son','the potter’s kiln','water, lotus and dūrvā'],
 lead='A poor widow’s little son survives a burning kiln.',
 steps=['In the days of King Hariścandra lived a brahmin, <b>Ṛṣiśarmā</b>, who died soon after his son was born; his widow raised the boy by begging.','In Māgha she kept the vow: she shaped a Gaṇeśa from cow dung and made ten sesame laḍḍus from her alms.','Her five-year-old tied the little Gaṇeśa round his neck and went to play. A potter whose pots would not fire had been told by a sorcerer to sacrifice a child; he seized the boy and sealed him in his kiln.','The mother searched and prayed all night. At dawn the potter opened the kiln: it was full of water to the boy’s knees, lotuses and dūrvā grew there, and the child was playing.','The potter confessed to the king; the widow said it was the vow’s power, not hers, and the king ordered the vow kept throughout the land.'],
 chars=[('👩','The widow','Poor, faithful, and clear that the power was the vow’s.'),('👦','Her son','Who wears the little Gaṇeśa and survives the fire.'),('🏺','The potter','Misled by a sorcerer into a terrible act.'),('👑','Hariścandra','The just king who hears the case.')],
 fruits='Protection of children; the fulfilment of every wish.',
 custom='In the north this is Sakaṭ Cauth (Tilkuṭ Cauth), kept by mothers for their children with sesame sweets.',
 talk=[('z','Lotuses in a kiln!'),('b','Fire turned to a pond. The image says Gaṇeśa can cool any fire you’re put in.')],
 k='Fire turned <b>to water</b>',
 lesson=['<b>Humility.</b> The widow refuses credit; the vow, not she, saved the child.','<b>Simple means.</b> A cow-dung Gaṇeśa and laḍḍus made from alms are enough.'])
e(slug='dvijapriya',name='Dvijapriya',mon='Māgha',pm='Phālguna',form='Dvijapriya Mahāgaṇapati',pitha='Sāmānya-deva pīṭha',
 mean='“dear to the twice-born”, to the learned and devout',
 teller=CORE,
 offering='The vrata book names kheer offered in a homa, with ghee and sugar in the day’s food.',
 strip=[panel([(S('#ff8c1a'),.8),(Q('#c0392b'),.7),(Q('#7a3fa0'),.7)],'#fff3cf',140),panel([(Q('#2a9d6f'),.8),(S('#ff8c1a'),.8),(lamp(),1)],'#2a2a3a',140),panel([(Q('#2a9d6f'),.8),(pot('#e0a800'),1)],'#fde4e4',140)],
 caps=['six refuse','the youngest helps','a house full of gems'],
 lead='An old father-in-law, seven daughters-in-law, and one who said yes.',
 steps=['In King Yuvanāśva’s land, the scholar <b>Viṣṇuśarmā</b> had seven prosperous sons who lived apart; in old age he ate at each house in turn and was treated with growing contempt.','On Saṅkaṣṭī he asked his eldest daughter-in-law for the things for worship. She mocked him; so did the next five.','The youngest, very poor, begged for what was needed, made laḍḍus, helped him worship, fed him, and fasted herself.','At midnight the old man fell ill and soiled himself; she cleaned him and stayed awake, lamenting her bad luck.','At dawn her house was full of gems and his pain was gone. He called her <b>Sulakṣaṇī</b>, “the one of good marks”; her jealous sisters-in-law later took up the vow too.'],
 chars=[('👴','Viṣṇuśarmā','The neglected old scholar.'),('🌸','The youngest daughter-in-law','Poor, kind, and patient through the night.'),('😤','The six elder ones','Who mock him and later regret it.'),('👑','Yuvanāśva','The just king of the land.')],
 fruits='Prosperity and the end of hardship; in Kṛṣṇa’s words, a lasting kingdom.',
 custom='This Saṅkaṣṭī falls in Māgha, the month of holy bathing.',
 talk=[('z','So the real vow was looking after him?'),('b','Exactly. Service to the old man was the worship. The gems are just the story’s way of saying so.')],
 k='Service <b>is</b> worship',
 lesson=['<b>Care of the old.</b> The story is a sharp mirror for families that neglect their elders.','<b>Patience through the unpleasant.</b> The youngest serves even in the night’s mess; that is the test she passes.'])
e(slug='bhalacandra',name='Bhālacandra',mon='Phālguna',pm='Caitra',form='Bhālacandra Mahāgaṇapati',pitha='Āgama pīṭha',
 mean='“with the moon on his forehead” (bhāla: forehead, candra: moon)',
 teller=CORE,
 offering='A whole-day fast, ṣoḍaśopacāra worship, and pañcagavya taken before the fast is broken.',
 strip=[panel([(K('#e0a800'),.8),(child(),.9)],'#fff3cf',140),panel([(Q('#c0392b'),.8),(Q('#7a3fa0'),.8)],'#fde4e4',140),panel([(K('#e0a800'),.8),(Q('#c0392b'),.7),(child(),.8)],'#e3f2e3',140)],
 caps=['the prince is born','the vow is mocked','the prince returns'],
 lead='A minister’s family mocks a young wife’s vow, until the crown prince disappears.',
 steps=['King <b>Mayūradhvaja</b> at last had a son by sage Yājñavalkya’s blessing, and left affairs to his minister <b>Dharmapāla</b>.','Dharmapāla’s youngest daughter-in-law kept the Saṅkaṣṭī vow. Her mother-in-law accused her of sorcery and turned her husband against her.','She finished the vow anyway and prayed that her family’s faith be restored. Soon the crown prince vanished, and his clothes were found in Dharmapāla’s house.','The king threatened the minister with death. At home the young wife said the insult to Gaṇeśa was the cause, and taught them the vow.','King, minister and people all kept it; the prince was returned, and the king honoured her and told everyone to keep Saṅkaṣṭī.'],
 chars=[('👑','Mayūradhvaja','The king whose son vanishes.'),('📜','Dharmapāla','The minister under threat.'),('🌸','The young wife','Faithful despite her family; called Sulakṣaṇī.'),('🤴','The prince','Hidden by Gaṇeśa and returned.')],
 fruits='Removal of all obstacles; Kṛṣṇa tells Yudhiṣṭhira that he regained his kingdom by it.',
 custom='This is the last Saṅkaṣṭī of the year in Karnataka’s calendar, just before Ugādi. Its name ties it to the moon; see '+'Part 3'+'.',
 talk=[('z','Gaṇeśa kidnapped a prince?'),('b','Story logic: a shock to make a proud family listen. No one was harmed and everyone learned.')],
 k='A faithful wife <b>turns a household</b>',
 lesson=['<b>Respect another’s practice.</b> Calling a young wife’s worship “sorcery” is the family’s real fault.','<b>Faith spreads.</b> One woman’s quiet vow becomes the whole kingdom’s.'])
e(slug='vibhuvana-palaka',name='Vibhuvanapālaka',mon='Adhika Māsa',pm='Adhika Māsa',form='Vibhuvanapālaka Mahāgaṇapati',pitha='Dūrvā-bilva-patra pīṭha',
 mean='“protector of the worlds”, the form for the extra month',
 teller='No traditional story for this month could be verified. Lists of thirteen Saṅkaṣṭīs name the form and seat, and say a thirteenth story is read, but the stories now circulating are modern devotional writing. We tell none.',
 offering='As in every month: dūrvā, modakas, a lamp, and arghya to the moon.',
 strip=[panel([(G(),.55)],'#fff3cf',140),panel([(durva(),1.6),(leaf(),1.2)],'#cfe0b8',140),panel([(moon(),2)],'#2a2a3a',140)],
 caps=['Gaṇeśa of all worlds','a seat of dūrvā and bilva','the extra moon'],
 lead='The thirteenth Saṅkaṣṭī comes only in a year with a leap month.',
 steps=['The lunar year is about eleven days shorter than the solar year, so roughly every third year a month is added: <b>Adhika Māsa</b>.','A Saṅkaṣṭī falls in that month too, the thirteenth of the year.','Its form is <b>Vibhuvanapālaka</b>, protector of the worlds, and its seat is of dūrvā grass and bilva leaves, the leaves dear to Gaṇeśa and Śiva.','Adhika Māsa is also called <b>Puruṣottama Māsa</b>, given over to Viṣṇu; worship in it is said to be specially fruitful.','Keep it like any Saṅkaṣṭī: fast to moonrise, worship, read a story (many read the Gajānana story or the Saṅkaṭanāśana stotra), offer arghya, break the fast.'],
 chars=[('🐘','Vibhuvanapālaka','Gaṇeśa as protector of every world.'),('🌿','Dūrvā','The grass most dear to Gaṇeśa.'),('🍃','Bilva','The three-fold leaf, dear to Śiva.'),('📅','Adhika Māsa','The leap month that makes room for this vow.')],
 fruits='The general fruit of Saṅkaṣṭī: removal of obstacles.',
 custom='It comes only in leap years; check your pañcāṅga.',
 talk=[('z','No story at all?'),('b','None we could trace to an old text. Better an honest gap than an invented tale.')],
 k='The rare <b>thirteenth</b>',
 lesson=['<b>Honesty in tradition.</b> Where the old texts are silent, we say so.','<b>Extra time, extra devotion.</b> A leap month is treated as a gift of time to give back to God.'])
